/**
 * Procedural app icon.
 *
 * The project rule is that every binary asset is generated by code in the repo,
 * and an icon is no exception: it is drawn pixel by pixel here, encoded as PNG
 * with `node:zlib` (no native image libraries), and written by `npm run assets`.
 *
 * The mark is a dungeon gate with an ember inside it: readable at 48 px, dark
 * enough to sit on the Telegram app grid, and made only of the game's palette.
 */
import { deflateSync } from 'node:zlib';

export interface IconOptions {
  readonly size: number;
  /** Adds the maskable safe zone: the mark shrinks to 80 % of the canvas. */
  readonly maskable?: boolean;
}

const BACKGROUND = [11, 14, 20] as const;
const STONE = [42, 46, 56] as const;
const GOLD = [201, 162, 39] as const;
const EMBER = [232, 138, 48] as const;
const EMBER_HOT = [255, 214, 130] as const;

interface Rgb {
  readonly 0: number;
  readonly 1: number;
  readonly 2: number;
}

function mix(a: Rgb, b: Rgb, t: number): [number, number, number] {
  const clamped = Math.min(1, Math.max(0, t));
  return [
    Math.round(a[0] + (b[0] - a[0]) * clamped),
    Math.round(a[1] + (b[1] - a[1]) * clamped),
    Math.round(a[2] + (b[2] - a[2]) * clamped),
  ];
}

/**
 * Signed distance to an arch: a semicircle on top of a straight opening.
 * Negative inside, positive outside, roughly in normalized units.
 */
function sdArch(px: number, py: number, radius: number, bottom: number): number {
  if (py < 0) return Math.hypot(px, py) - radius;
  return Math.max(Math.abs(px) - radius, py - bottom);
}

/** Anti-aliased coverage of a band of half-thickness `t` around a shape edge. */
function band(distance: number, halfThickness: number, softness: number): number {
  const outer = halfThickness + softness;
  return Math.min(1, Math.max(0, (outer - Math.abs(distance)) / softness)) * (Math.abs(distance) < halfThickness + softness ? 1 : 0);
}

/**
 * Renders RGBA pixels for the icon.
 *
 * Everything is expressed in normalized coordinates so the same drawing works
 * for 192 px, 512 px and any future size: a stone gate with an ember burning in
 * the opening — the game in one glyph, readable down to 48 px.
 */
export function renderIcon({ size, maskable = false }: IconOptions): Uint8Array {
  const pixels = new Uint8Array(size * size * 4);
  const scale = maskable ? 0.78 : 1;
  const centre = size / 2;
  const superSample = 2;

  for (let y = 0; y < size; y += 1) {
    for (let x = 0; x < size; x += 1) {
      let r = 0;
      let g = 0;
      let b = 0;
      // 2x2 supersampling: the arch edge is the only hard edge on the icon and
      // a stair-stepped gate looks like a bug at 192 px.
      for (let sy = 0; sy < superSample; sy += 1) {
        for (let sx = 0; sx < superSample; sx += 1) {
          const px = x + (sx + 0.5) / superSample;
          const py = y + (sy + 0.5) / superSample;
          const nx = (px - centre) / (centre * scale);
          const ny = (py - centre) / (centre * scale);
          const colour = shade(nx, ny);
          r += colour[0];
          g += colour[1];
          b += colour[2];
        }
      }
      const samples = superSample * superSample;
      const offset = (y * size + x) * 4;
      pixels[offset] = Math.round(r / samples);
      pixels[offset + 1] = Math.round(g / samples);
      pixels[offset + 2] = Math.round(b / samples);
      pixels[offset + 3] = 255;
    }
  }

  return pixels;
}

/** Colour of one sample at normalized coordinates, back to front. */
function shade(nx: number, ny: number): [number, number, number] {
  // Background: slate vignette, dark enough for the Telegram app grid.
  const radius = Math.hypot(nx, ny);
  let colour = mix(STONE, BACKGROUND, Math.min(1, radius / 1.15));

  // Gate: stone-gold arch with a dark opening.
  const gate = sdArch(nx * 0.94, ny + 0.08, 0.44, 0.56);
  const rim = band(gate, 0.1, 0.01);
  if (rim > 0) {
    // Lit from above: the top of the arch catches more of the ember light.
    const light = Math.min(1, Math.max(0, 0.55 + (0.2 - ny) * 0.45));
    const stone = mix(STONE, GOLD, 0.35 + 0.65 * light);
    colour = mix(colour, stone, rim);
  }

  // Floor: a lit slab the gate stands on, drawn last so it is never hidden.
  const slab = Math.abs(ny - 0.66) - 0.035;
  if (slab < 0) {
    const fade = 1 - Math.abs(nx) / 0.8;
    colour = mix(colour, GOLD, 0.5 * Math.max(0.15, fade) * band(slab, 0.035, 0.015));
  }

  // Ember in the opening: warm halo, gold body, white-hot core.
  const emberDistance = Math.hypot(nx, ny - 0.16);
  if (emberDistance < 0.3) {
    const halo = Math.max(0, 1 - emberDistance / 0.3) ** 1.7;
    colour = mix(colour, EMBER, halo * 0.35);
    if (emberDistance < 0.17) {
      const body = (1 - emberDistance / 0.17) ** 0.9;
      colour = mix(colour, EMBER, body);
      if (emberDistance < 0.07) colour = mix(colour, EMBER_HOT, 1 - emberDistance / 0.07);
    }
  }

  return colour;
}

const CRC_TABLE = (() => {
  const table = new Uint32Array(256);
  for (let n = 0; n < 256; n += 1) {
    let c = n;
    for (let k = 0; k < 8; k += 1) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    table[n] = c >>> 0;
  }
  return table;
})();

function crc32(bytes: Uint8Array): number {
  let c = 0xffffffff;
  for (const byte of bytes) c = (CRC_TABLE[(c ^ byte) & 0xff] ?? 0) ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}

function chunk(type: string, data: Uint8Array): Buffer {
  const length = Buffer.alloc(4);
  length.writeUInt32BE(data.length, 0);
  const typeAndData = Buffer.concat([Buffer.from(type, 'ascii'), Buffer.from(data)]);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(typeAndData), 0);
  return Buffer.concat([length, typeAndData, crc]);
}

/** Encodes RGBA pixels as a true-colour PNG (filter 0 on every scanline). */
export function encodePng(rgba: Uint8Array, size: number): Buffer {
  const header = Buffer.alloc(13);
  header.writeUInt32BE(size, 0);
  header.writeUInt32BE(size, 4);
  header[8] = 8; // bit depth
  header[9] = 6; // colour type: RGBA
  header[10] = 0; // deflate
  header[11] = 0; // adaptive filtering
  header[12] = 0; // no interlace

  const stride = size * 4;
  const raw = Buffer.alloc((stride + 1) * size);
  for (let y = 0; y < size; y += 1) {
    raw[y * (stride + 1)] = 0;
    Buffer.from(rgba.buffer, rgba.byteOffset + y * stride, stride).copy(raw, y * (stride + 1) + 1);
  }

  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk('IHDR', header),
    chunk('IDAT', deflateSync(raw, { level: 9 })),
    chunk('IEND', new Uint8Array()),
  ]);
}

export interface IconArtifact {
  readonly file: string;
  readonly size: number;
  readonly bytes: Buffer;
  readonly maskable: boolean;
}

/** Every icon the web app manifest and iOS home screen need. */
export function buildIcons(): IconArtifact[] {
  const specs: { file: string; size: number; maskable?: boolean }[] = [
    { file: 'icons/icon-192.png', size: 192 },
    { file: 'icons/icon-512.png', size: 512 },
    { file: 'icons/maskable-512.png', size: 512, maskable: true },
  ];
  return specs.map((spec) => ({
    file: spec.file,
    size: spec.size,
    maskable: spec.maskable === true,
    bytes: encodePng(renderIcon({ size: spec.size, maskable: spec.maskable === true }), spec.size),
  }));
}
